/* Multi-person plans and optional creation drafts, separate from paid dialogue. */
(() => {
 const el=id=>document.getElementById(id);let planner=null,groupSignature='',creating=null,creationActor='player',creationMode='current',characterProposal=null,characterBusy=false,characterDraftVersion=0,groupDrafts=new Map();
 const option=(select,value,label)=>{const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o);};
 async function local(path,body){const res=await fetch(path,{headers:{'X-Play-Token':token,...(body?{'Content-Type':'application/json'}:{})},...(body?{method:'POST',body:JSON.stringify(body)}:{})});const data=await res.json();if(!res.ok)throw Error(data.message||'設定暫時無法讀取');return data;}
 function note(text,error=false){el('social-status').textContent=text;el('social-status').classList.toggle('error',error);}
 function when(tick){let t=840+tick;return `DAY ${1+Math.floor(t/1440)} · ${String(Math.floor(t%1440/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;}
 function catalog(){const venue=planner.venues.find(v=>v.id===el('social-venue').value);const s=el('social-item');s.replaceChildren();option(s,'','自由散步／聊天 · 每人 0 代幣');for(const r of venue.items)option(s,r.id,`${r.title} · 每人 ${r.price} 代幣 · ${r.minutes} 分鐘`);}
 window.renderSocial=s=>{const groups=s.social?.groups||[];el('social-open').textContent=`共同活動${groups.filter(g=>['planned','active'].includes(g.status)).length?' · '+groups.filter(g=>['planned','active'].includes(g.status)).length:''}`;if(el('social-modal').open&&groupSignature!==JSON.stringify(groups)){groupSignature=JSON.stringify(groups);paintGroups(groups);}};
 function paintGroups(groups){
  const list=el('social-groups');for(const card of list.querySelectorAll('[data-group-id]')){const text=card.querySelector('[data-role=message]'),speaker=card.querySelector('[data-role=speaker]');if(text)groupDrafts.set(card.dataset.groupId,{text:text.value,speaker:speaker?.value||''});}list.replaceChildren();
  if(!groups.length){const p=document.createElement('p');p.textContent='還沒有共同活動。選好地點和成員，發出第一個邀約。';list.append(p);return;}
  const statuses={planned:'等待集合',active:'活動進行中',completed:'已完成',cancelled:'已取消',missed:'未成行'};const responses={pending:'待回覆',accepted:'接受',declined:'婉拒',missed:'沒趕上',expired:'已過期',left:'已退出'};
  for(const g of [...groups].reverse()){
   const card=document.createElement('section');card.className='art-job';card.dataset.groupId=g.id;const title=document.createElement('h4');title.textContent=`${g.title} · ${statuses[g.status]}`;card.append(title);
   const detail=document.createElement('p');detail.textContent=`${state.location_names[g.venue]||g.venue} · ${when(g.start)} · ${g.item_title} · 每人 ${g.price} 代幣`;card.append(detail);
   const members=document.createElement('p');members.textContent=g.members.map(m=>`${m.name}：${g.attendees.includes(m.id)?'已到場':responses[g.responses[m.id]]}`).join('　');card.append(members);
   const toolbar=document.createElement('div');toolbar.className='art-toolbar';
   function button(label,command,params){const b=document.createElement('button');b.textContent=label;b.onclick=async()=>{await send(command,params);note(state.notice||'已更新活動安排。',!!state.error);};toolbar.append(b);}
   if(g.status==='planned'){
    if(g.self_response==='pending'){button('接受邀約','group_respond',{group:g.id,accept:true});button('婉拒','group_respond',{group:g.id,accept:false});}
    if(g.self_response==='accepted')button(g.arrived?'已到集合點 · 可再次定位':'前往集合點','group_go',{group:g.id});
    if(g.host==='player')button('取消活動','group_cancel',{group:g.id});else if(g.self_response==='accepted')button('退出活動','group_leave',{group:g.id});
   }else if(g.status==='active'&&g.attendees.includes('player'))button('離開活動','group_leave',{group:g.id});
   card.append(toolbar);
   if(g.messages.length){const log=document.createElement('div');log.className='social-log';log.setAttribute('role','log');for(const m of g.messages.slice(-12)){const p=document.createElement('p');p.textContent=`${g.members.find(x=>x.id===m.actor)?.name||m.actor}：${m.text}`;window.attachSpeech?.(p,m.id,m.actor,m.text);log.append(p);}card.append(log);}
   if(g.can_speak){
    const form=document.createElement('form');form.className='social-talk';const input=document.createElement('input');input.type='text';input.maxLength=1200;input.placeholder='對這次活動的成員說些什麼…';input.setAttribute('aria-label',`${g.title}群聊訊息`);input.dataset.role='message';input.value=groupDrafts.get(g.id)?.text||'';
    const speaker=document.createElement('select');speaker.dataset.role='speaker';speaker.setAttribute('aria-label',`${g.title}接話成員`);option(speaker,'','只送出訊息 · 不扣 API');for(const id of g.attendees.filter(a=>a!=='player'))option(speaker,id,`${g.members.find(m=>m.id===id)?.name}接話 · Grok 4.3`);speaker.value=groupDrafts.get(g.id)?.speaker||'';
    const b=document.createElement('button');b.type='submit';b.textContent='送出';form.append(input,speaker,b);form.onsubmit=async e=>{e.preventDefault();const text=input.value.trim();if(!text||busy)return;groupDrafts.set(g.id,{text:'',speaker:speaker.value});input.value='';await send('group_talk',{group:g.id,text,speaker:speaker.value});note(state.error?.message||'訊息已送給實際參與的成員。',!!state.error);};
    const reply=document.createElement('button');reply.type='button';reply.textContent='請所選成員接話 · 1 次 API';reply.onclick=async()=>{if(!speaker.value){note('先選一位到場成員。');return;}await send('group_reply',{group:g.id,speaker:speaker.value});note(state.error?.message||'她已做出自己的回應。',!!state.error);};form.append(reply);card.append(form);
   }
   list.append(card);
  }
 }
 el('social-open').onclick=async()=>{if(!state)return;game.keys.clear();el('social-modal').showModal();try{planner=await local('/api/groups');const select=el('social-venue');select.replaceChildren();for(const v of planner.venues)option(select,v.id,v.name);select.value=planner.venues.some(v=>v.id===state.space.scene)?state.space.scene:'park';catalog();const people=el('social-people');people.replaceChildren();for(const p of state.roster){const label=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.value=p.id;label.append(box,document.createTextNode(p.name));people.append(label);}note(planner.rules);groupSignature='';renderSocial(state);}catch(e){note(e.message,true);}};
 el('social-close').onclick=()=>el('social-modal').close();el('social-modal').addEventListener('close',()=>game.keys.clear());el('social-venue').onchange=catalog;
 el('social-create-form').onsubmit=async e=>{e.preventDefault();const participants=[...el('social-people').querySelectorAll('input:checked')].map(x=>x.value);if(!participants.length){note('至少選一位同伴。',true);return;}await send('group_create',{venue:el('social-venue').value,item:el('social-item').value,title:el('social-title').value.trim()||'一起出門走走',participants,start:state.tick+Number(el('social-delay').value),duration:Number(el('social-duration').value)});note(state.error?.message||state.notice,!!state.error);};
 function rows(){return creationMode==='current'?creating.current:creating.profiles;}
 async function refreshCharacters(appliedActor){storeDraft();const previous=creating,next=await local('/api/characters');for(const [id,p] of Object.entries(previous.current))if(id!==appliedActor&&previous.fingerprints[id]===next.fingerprints[id])next.current[id]=p;next.profiles=previous.profiles;creating=next;}
 function clearCharacterPreview(){characterDraftVersion++;characterProposal=null;el('creation-apply').disabled=true;el('creation-preview').textContent='';}
 function storeDraft(){if(!creating)return;rows()[creationActor]={name:el('creation-name').value,age:Number(el('creation-age').value),gender:el('creation-gender').value,voice:el('creation-voice').value,goal:el('creation-goal').value,appearance:el('creation-appearance').value,look:window.CharacterMaker?.readLook(rows()[creationActor].look)||rows()[creationActor].look,background_enabled:el('creation-background-enabled').checked,background:el('creation-background').value};}
 function paintPeople(){const select=el('creation-person');select.replaceChildren();for(const [id,p] of Object.entries(rows()))option(select,id,`${id==='player'?'玩家':'共居角色'} · ${p.name}`);select.value=creationActor;}
 function showCharacter(){clearCharacterPreview();const p=rows()[creationActor];el('creation-name').value=p.name;el('creation-age').value=p.age;el('creation-gender').value=p.gender|| (creationActor==='player'?'male':'female');el('creation-voice').value=p.voice;el('creation-goal').value=p.goal;el('creation-appearance').value=p.appearance||'';el('creation-background-enabled').checked=p.background_enabled;el('creation-background').value=p.background;el('creation-background-field').hidden=!p.background_enabled;el('creation-save').hidden=creationMode!=='template';el('creation-live').hidden=creationMode!=='current';el('creation-new').hidden=creationMode!=='template';window.CharacterMaker?.show(p,creationActor,creationMode);}
 function paintArchives(){const select=el('creation-archive');select.replaceChildren();option(select,'','選擇原存檔');for(const a of creating.archives||[])option(select,a.id,a.label);el('creation-restore').disabled=!creating.archives?.length;}
 window.CharacterBridge={read(){storeDraft();return {actor:creationActor,profile:structuredClone(rows()[creationActor]),mode:creationMode};},accept(p){rows()[creationActor]=p;showCharacter();},invalidate:clearCharacterPreview};
 const creationNote=(text,error=false)=>{el('creation-status').textContent=text;el('creation-status').classList.toggle('error',error);};
 window.openCharacterMaker=async(mode,actor)=>{if(!state)return;game.keys.clear();if(mode)creationMode=mode;if(actor)creationActor=actor;el('creation-modal').showModal();try{creating=await local('/api/characters');el('creation-mode').value=creationMode;paintPeople();showCharacter();paintArchives();creationNote(creating.applies);}catch(e){creationNote(e.message,true);}};window.resumeCharacterMaker=()=>{el('creation-modal').showModal();paintPeople();showCharacter();};el('creation-open').onclick=()=>window.openCharacterMaker();
 el('creation-close').onclick=()=>{storeDraft();el('creation-modal').close();};el('creation-modal').addEventListener('close',()=>game.keys.clear());
 el('creation-person').onchange=()=>{storeDraft();creationActor=el('creation-person').value;showCharacter();};el('creation-background-enabled').onchange=()=>{clearCharacterPreview();el('creation-background-field').hidden=!el('creation-background-enabled').checked;};
 el('creation-mode').onchange=()=>{storeDraft();creationMode=el('creation-mode').value;paintPeople();showCharacter();creationNote(creationMode==='current'?'修改目前人物：先預覽，再套用；保留記憶、錢包與進度。':'新遊戲模板：保存後只在建立新存檔時採用。');};
 for(const id of ['creation-name','creation-age','creation-gender','creation-voice','creation-goal','creation-appearance','creation-background'])el(id).addEventListener('input',clearCharacterPreview);
 el('creation-prepare').onclick=async()=>{if(characterBusy||!creating)return;characterBusy=true;el('creation-prepare').disabled=true;try{storeDraft();const actor=creationActor,version=characterDraftVersion,p=await local('/api/characters',{operation:'prepare_current',actor,profile:creating.current[actor],before:creating.fingerprints[actor]});if(creationActor!==actor||creationMode!=='current'||version!==characterDraftVersion)return;characterProposal=p;el('creation-preview').textContent=p.changes.flatMap(c=>c.diff.map(d=>`${d.field}: ${d.before} → ${d.after}`)).join('\n')||'設定沒有差異。';el('creation-apply').disabled=false;creationNote('驗證通過，尚未套用。背景與性格只進入這位人物自己的設定；圖片需生成或匯入後套用。');}catch(e){clearCharacterPreview();creationNote(e.message,true);}finally{characterBusy=false;el('creation-prepare').disabled=false;}};
 el('creation-apply').onclick=async()=>{if(characterBusy||!characterProposal)return;characterBusy=true;el('creation-apply').disabled=true;const appliedActor=creationActor;try{await local('/api/components',{operation:'apply',params:{proposal:characterProposal.id}});clearCharacterPreview();await refreshCharacters(appliedActor);paintPeople();showCharacter();paintArchives();await send('ui_hold',{},true);creationNote('人物設定已套用；原記憶與進度保留。可在部件工坊的替換紀錄中還原。');}catch(e){clearCharacterPreview();creationNote(e.message,true);}finally{characterBusy=false;}};
 for(const [id,target] of [['creation-art','art-open'],['creation-assets','assets-open'],['creation-speech','speech-open']])el(id).onclick=()=>{storeDraft();if(id==='creation-art')window.characterArtIntent=creationActor;el('creation-modal').close();el(target).click();};
 async function saveCreation(){storeDraft();creating=await local('/api/characters',{profiles:creating.profiles});paintPeople();showCharacter();creationNote('創角模板已保存；現有世界與人物記憶保持原狀。');paintArchives();}
 el('creation-save').onclick=async()=>{try{await saveCreation();}catch(e){creationNote(e.message,true);}};
 el('creation-start').onclick=async()=>{if(!el('creation-new-confirm').checked){creationNote('勾選「建立新的存檔」後才能創角；原存檔將保留。',true);return;}try{await saveCreation();const result=await send('create_cast');if(result.failed||result.error)throw Error(result.notice||result.error.message);el('creation-new-confirm').checked=false;creating=await local('/api/characters');paintPeople();showCharacter();paintArchives();creationNote(state.notice||'已建立新角色。');window.LifeMenu?.enterWorld();el('creation-modal').close();}catch(e){creationNote(e.message,true);}};
 el('creation-restore').onclick=async()=>{const archive=el('creation-archive').value;if(!archive){creationNote('先選擇原存檔。');return;}try{await send('restore_cast',{archive});creating=await local('/api/characters');paintPeople();showCharacter();paintArchives();creationNote(state.notice||'原存檔已恢復，API 用量不會回退。');}catch(e){creationNote(e.message,true);}};
})();
